param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'argument-null-exception-serialization-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$constructors=@{};foreach($family in @('base','file')){$native=if($family -eq 'base'){[Exception]}else{[ArgumentNullException]};foreach($entry in @(@{key='default';types=[type[]]@()},@{key='message';types=[type[]]@([string])},@{key='inner';types=[type[]]@([string],[Exception])},@{key='file';types=[type[]]@([string],[string])},@{key='file-inner';types=[type[]]@([string],[string],[Exception])})){if($family -eq 'base' -and $entry.key.StartsWith('file')){continue};$constructors[$family+':'+$entry.key]=$native.GetConstructor($entry.types)}};$rows=[Collections.Generic.List[object]]::new();$controls=[Collections.Generic.List[object]]::new();$nullArgumentControls=0
foreach($flag in $plan.contextFlags){$context=[Runtime.Serialization.StreamingContext]::new([Runtime.Serialization.StreamingContextStates]$flag);foreach($observe in $plan.observeMessage){for($index=0;$index -lt $plan.cases.Count;$index++){$spec=$plan.cases[$index];$message=$null;$fileName=$null;if($null -ne $plan.messages[$spec.messageIndex]){$message=[string]::new([char[]]([int[]]$plan.messages[$spec.messageIndex]))};if($null -ne $plan.files[$spec.fileIndex]){$fileName=[string]::new([char[]]([int[]]$plan.files[$spec.fileIndex]))};$inner=$null;if($spec.inner -eq 'plain'){$inner=[Exception]::new()}elseif($spec.inner -eq 'named'){$inner=[Exception]::new('inner')};switch($spec.route){'default'{$arguments=[object[]]::new(0)};'message'{$arguments=[object[]]::new(1);$arguments[0]=$message};'inner'{$arguments=[object[]]::new(2);$arguments[0]=$message;$arguments[1]=$inner};'file'{$arguments=[object[]]::new(2);$arguments[0]=$fileName;$arguments[1]=$message};'file-inner'{$arguments=[object[]]::new(3);$arguments[0]=$message;$arguments[1]=$fileName;$arguments[2]=$inner}};if($spec.route -ne 'default' -and $null -eq $message){if($null -ne $arguments[$(if($spec.family -eq 'file' -and $spec.route -eq 'file'){1}else{0})]){throw 'Null message coerced'};$nullArgumentControls++};$e=$constructors[$spec.family+':'+$spec.route].Invoke($arguments);if($observe){$null=$e.Message};$info=[Runtime.Serialization.SerializationInfo]::new($e.GetType(),[Runtime.Serialization.FormatterConverter]::new());$e.GetObjectData($info,$context);$entries=[Collections.Generic.List[object]]::new();$enumerator=$info.GetEnumerator();while($enumerator.MoveNext()){$entry=$enumerator.Current;$value=$entry.Value;$kind='null';$units=$null;$number=$null;if($null -ne $value){if([object]::ReferenceEquals($value,$inner)){$kind='inner'}elseif($value -is [string]){$kind='text';$units=[int[]][char[]]$value}elseif($value -is [int]){$kind='int';$number=$value}else{throw "Unexpected serialization value: $($entry.Name) $($value.GetType().FullName)"}};$entries.Add([ordered]@{name=$entry.Name;type=$entry.ObjectType.FullName;kind=$kind;units=$units;number=$number})};$rows.Add([ordered]@{index=$index;contextFlag=$flag;observeMessage=[bool]$observe;memberCount=$info.MemberCount;entries=$entries.ToArray()})}};foreach($family in @('base','file')){$e=$constructors[$family+':default'].Invoke([object[]]@());try{$e.GetObjectData($null,$context);throw 'Expected null-info failure'}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};if($errorValue -isnot [ArgumentNullException]){throw};$controls.Add([ordered]@{family=$family;contextFlag=$flag;exception=$errorValue.GetType().FullName;paramName=$errorValue.ParamName;hResult=$errorValue.HResult;messageUnits=[int[]][char[]]$errorValue.Message})}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';nullArgumentControls=$nullArgumentControls;rows=$rows.ToArray();controls=$controls.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 22 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS exception/file serialization: $($rows.Count) payloads and $($controls.Count) null controls"
